// Interface icons for the app: the same Solar set as the landing page (src/landing/solar.ts, generated by
// scripts/solar-icons.mjs; CC BY 4.0, credited in the landing footer). Decorative: pair with text or a label.
import { SOLAR, type SolarName } from "../landing/solar";

export function Icon({ name, className = "icon" }: { name: SolarName; className?: string }) {
  return <svg viewBox="0 0 24 24" aria-hidden="true" className={className} dangerouslySetInnerHTML={{ __html: SOLAR[name] }} />;
}
